        include 'Figures\Scripts\Vectors.inc';

        W := 0.55;
        DCut1 := W * 0.75;

        s3 := sqrt(3);

        N := 9;
        M1 := N div 2; // (N-1) / 2; // 4
        M2 := M1 div 2; // 2
        AXA := 2*Pi * M1 / N;

        for i := 0 to 2 do begin
            ax[i] := cos(2 * Pi / 3 * i);
            ay[i] := sin(2 * Pi / 3 * i);
        end;
        az := sqrt(3 / (1 - 2 * cos(AXA)) - 1); // = tan(a); // where a is an angle between axis and horizontal plane

        jAngle := ArcCos((2 * az^2 - 1) / (4 * az^2 + 1));

        VectorRotatePoint(-1/2, s3/2, az,  -2, 0, az,  -2*Pi / N * M2, True);

        DCut2 := (-W * az * Ans_X + Ans_Z * W) / sqrt(1 + az^2);

